    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我悄悄漏着气 轻得像羽毛"
        },
        {
          "id": "V1-02",
          "zh": "你伸进我的胸口 一件件掏空"
        },
        {
          "id": "V1-03",
          "zh": "什么都吸进来 不剩一点"
        },
        {
          "id": "V1-04",
          "zh": "一口一口咽下 影子不见"
        },
        {
          "id": "V1-05",
          "zh": "我正一点一点 皱成一团纸"
        },
        {
          "id": "V1-06",
          "zh": "心口最里面那块 洗不掉的黑渍"
        },
        {
          "id": "V1-07",
          "zh": "你顺手就替我洗得 一点不留"
        },
        {
          "id": "V1-08",
          "zh": "我什么都不用做 就会很好"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我正在一天一天变得更轻"
        },
        {
          "id": "V1-02",
          "zh": "你总是把一切都全部夺干净"
        },
        {
          "id": "V1-03",
          "zh": "无论什么事情都吸进去"
        },
        {
          "id": "V1-04",
          "zh": "吞了下去就再也回不来"
        },
        {
          "id": "V1-05",
          "zh": "我却正一天一天都没了劲"
        },
        {
          "id": "V1-06",
          "zh": "就连我内心深处那块黑色污渍"
        },
        {
          "id": "V1-07",
          "zh": "它们全都会被洗得干净俐落"
        },
        {
          "id": "V1-08",
          "zh": "什么也不用做就一切太平"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我渐渐变得轻盈"
        },
        {
          "id": "V1-02",
          "zh": "你把一切都夺去"
        },
        {
          "id": "V1-03",
          "zh": "无论什么都能吸入"
        },
        {
          "id": "V1-04",
          "zh": "全都吞噬殆尽"
        },
        {
          "id": "V1-05",
          "zh": "我渐渐变得虚弱"
        },
        {
          "id": "V1-06",
          "zh": "心中的黑色污渍"
        },
        {
          "id": "V1-07",
          "zh": "也被彻底洗净"
        },
        {
          "id": "V1-08",
          "zh": "于是什么都不用做也好"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V1-01",
          "zh": "我正越来越轻 像气球升空"
        },
        {
          "id": "V1-02",
          "zh": "你总把我的一切 都轻轻收走"
        },
        {
          "id": "V1-03",
          "zh": "什么都吸进去 一点不留"
        },
        {
          "id": "V1-04",
          "zh": "全吞下去之后 房间安静"
        },
        {
          "id": "V1-05",
          "zh": "我正越来越弱 像漏气气球"
        },
        {
          "id": "V1-06",
          "zh": "心口上那块黑渍 也被擦得发亮"
        },
        {
          "id": "V1-07",
          "zh": "你替我洗得干净 像空的房间"
        },
        {
          "id": "V1-08",
          "zh": "我什么都不用做 一切都好"
        }
      ]
    }
  ]
}

